import{_ as t,o,c as s,a2 as n}from"./chunks/framework.CZW044RH.js";const p=JSON.parse('{"title":"Debugging","description":"","frontmatter":{},"headers":[],"relativePath":"guide/debug.md","filePath":"guide/debug.md"}'),a={name:"guide/debug.md"};function i(d,e,c,r,h,l){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h1><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span></span></code></pre></div><p>Same loop as <code>sugr dev</code> (Vite + watch/restart), with backend and frontend debugging enabled independently - both land you on a real breakpoint in the app&#39;s own window.</p><div class="warning custom-block"><p class="custom-block-title">VS Code only, for now</p><p><code>sugr debug</code> auto-generates debug configs for <strong>VS Code</strong> only (<code>.vscode/launch.json</code>, see below) - that&#39;s the only IDE it wires up today. The underlying mechanisms (JDWP on port <code>5005</code>, CDP on port <code>9222</code>) aren&#39;t VS Code-specific, so attaching manually from another IDE or tool works too (e.g. IntelliJ&#39;s &quot;Remote JVM Debug&quot; for the backend, <code>chrome://inspect</code> or any CDP-compatible tool for the frontend) - you just have to set that up yourself; there&#39;s no auto-generated JetBrains/Neovim config yet.</p></div><ul><li><strong>Backend</strong>: appends Gradle&#39;s built-in <code>--debug-jvm</code> to the app launch, so the JVM suspends and waits for a debugger on port <code>5005</code> every time it (re)starts.</li><li><strong>Frontend</strong>: sets <code>WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS</code> (Windows/WebView2) or <code>WEBKIT_INSPECTOR_SERVER</code> (Linux/WebKitGTK, unverified like the rest of the Linux webview path) so the app&#39;s <em>own</em> webview exposes a Chrome DevTools Protocol endpoint on port <code>9222</code> - not a separate browser tab, the actual window the user sees, bridge calls (<code>invoke()</code>/<code>events</code>) included. macOS&#39;s WKWebView has no such env var; use Safari&#39;s Develop menu there for now.</li></ul><p>The first time you run it, <code>sugr debug</code> writes <code>.vscode/launch.json</code> in the current directory with two <code>&quot;attach&quot;</code> configs - <code>sugr: attach backend</code> (Java, port 5005) and <code>sugr: attach frontend</code> (<code>msedge</code>, port 9222, built into VS Code&#39;s bundled JS debugger, no extra extension needed). It only ever adds these two entries by name, leaving the rest of an existing <code>launch.json</code> untouched. Open the Run &amp; Debug panel, pick one (or both, as separate debug sessions), set a breakpoint in your Java or <code>.tsx</code> source, and it&#39;ll actually hit - the backend one every time the JVM (re)starts (suspend=y), the frontend one as soon as you attach.</p><p>Turn either side off independently:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-backend</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # frontend debugging only, backend just watches</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sugr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-frontend</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # backend debugging only, no CDP port</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">With both sides on, attach the backend first</p><p>The webview is created from inside <code>main()</code>, and with backend debugging on, <code>main()</code> never runs until <em>something</em> attaches on port <code>5005</code> (that&#39;s what <code>suspend=y</code> means). So if you leave both sides enabled, attaching <code>sugr: attach frontend</code> first fails with &quot;could not find any debuggable target&quot; - the window hasn&#39;t opened yet, so there&#39;s nothing on port <code>9222</code> to attach to. Attach <code>sugr: attach backend</code> first (even if you don&#39;t need a Java breakpoint yet) to let it past that point, then attach the frontend. Running with <code>--no-backend</code> sidesteps this entirely - the JVM starts immediately.</p></div>`,9)])])}const g=t(a,[["render",i]]);export{p as __pageData,g as default};
